import React,{createContext,useContext,useEffect,useMemo,useRef,useState} from 'react';import{createRoot}from'react-dom/client';import{BrowserRouter,Link,Route,Routes,useLocation,useNavigate,useParams}from'react-router-dom';import{Accessibility,ArrowLeft,ArrowRight,AudioLines,Bell,Check,Clock,Heart,Home as HomeIcon,Languages,MapPin,Mic,Phone,Printer,Search,Settings as SettingsIcon,Users,Volume2,Plus,RotateCcw,Radio,Download,QrCode}from'lucide-react';import{QRCodeSVG}from'qrcode.react';import{io}from'socket.io-client';import en from'./i18n/en.js';import hi from'./i18n/hi.js';import ta from'./i18n/ta.js';import{departments}from'./data/departments.js';import{floors,places,shortestPath}from'./data/hospital.js';import{samplePatients}from'./data/patients.js';import'./style.css';import'./animations.css';
