function FlyoverMap({route,destination}){const{t,lang}=useApp(),[playing,setPlaying]=useState(true);const point=p=>p.id==='entrance'?{x:48,y:263}:{x:90+p.x*4.05,y:242-p.floor*56-p.y*.43};const pts=route.map(point);const d=pts.length>1?pts.map((p,i)=>`${i?'L':'M'} ${p.x} ${p.y}`).join(' '):'M 90 242 L 300 145';const end=pts.at(-1)||{x:300,y:145};return <section className="flyover-card"><div className="flyover-heading"><span className="live-dot"/><div><b>{lang==='hi'?'अस्पताल का एनिमेटेड रास्ता':'Animated hospital route'}</b><small>{lang==='hi'?'नमूना अस्पताल · मुख्य प्रवेश से कैमरा दृश्य':'Sample hospital · camera view from the main entrance'}</small></div><button className="fly-toggle" onClick={()=>setPlaying(x=>!x)}>{playing?(lang==='hi'?'रोकें':'Pause'):(lang==='hi'?'चलाएँ':'Play')}</button></div><svg className={`flyover-svg ${playing?'is-playing':'is-paused'}`} viewBox="0 0 600 320" role="img" aria-label={lang==='hi'?'नमूना अस्पताल का ऊपर से एनिमेटेड नक्शा':'Animated overhead map of a fictional sample hospital'}><defs><linearGradient id="ground" x2="0" y2="1"><stop stopColor="#e4f1e8"/><stop offset="1" stopColor="#c9e1d4"/></linearGradient><linearGradient id="roof" x2="0" y2="1"><stop stopColor="#fffdf6"/><stop offset="1" stopColor="#c9d8cf"/></linearGradient><filter id="shadow"><feDropShadow dx="0" dy="5" stdDeviation="5" floodColor="#23594d" floodOpacity=".2"/></filter><path id="flightPath" d={d}/></defs><rect width="600" height="320" rx="22" fill="url(#ground)"/><path className="campus-road" d="M-10 278 C110 248 140 304 255 267 S425 252 610 286"/><path className="campus-road-line" d="M-10 278 C110 248 140 304 255 267 S425 252 610 286"/><g className="park-blocks"><path d="M25 35h135v65H25zM440 30h125v75H440zM35 180h78v55H35zM470 150h90v63h-90z"/><circle cx="70" cy="70" r="10"/><circle cx="510" cy="70" r="12"/><circle cx="78" cy="205" r="9"/><circle cx="520" cy="180" r="10"/></g><g filter="url(#shadow)" className="hospital-building"><path d="M190 126l113-58 116 58v113H190z" fill="url(#roof)" stroke="#73998b" strokeWidth="2"/><path d="M174 127l129-69 132 69h-28L303 80l-103 47z" fill="#247c70"/><rect x="277" y="157" width="52" height="82" rx="4" fill="#5a9386"/><g className="windows">{[0,1,2].map(r=>[0,1,2,3,4].map(c=><rect key={`${r}-${c}`} x={205+c*37} y={139+r*32} width="18" height="15" rx="3"/>))}</g><path d="M273 117h60" stroke="#d59647" strokeWidth="6"/><text x="303" y="108" textAnchor="middle">CITY DISTRICT HOSPITAL</text></g><g className="campus-spot" transform="translate(48 263)"><circle r="14"/><text y="28" textAnchor="middle">ENTRANCE</text></g><g className="destination-spot" transform={`translate(${end.x} ${end.y})`}><circle r="12"/><circle r="4"/><text y="25" textAnchor="middle">{placeName(places[destination]||places.room3,t).toUpperCase()}</text></g><path className="flight-route" d={d}/><path className="flight-glow" d={d}/><g className="drone" style={{offsetPath:`path('${d}')`,animationPlayState:playing?'running':'paused'}}><circle r="12"/><path d="M-7 0h14M0-7v14M-11-9h22M-11 9h22"/></g><g className="map-compass" transform="translate(548 48)"><circle r="20"/><path d="M0-13L5 4 0 1-5 4z"/><text y="34" textAnchor="middle">N</text></g><g className="floor-chip"><rect x="18" y="18" width="96" height="28" rx="14"/><text x="66" y="37" textAnchor="middle">{lang==='hi'?['भूतल','पहली मंजिल','दूसरी मंजिल'][places[destination]?.floor||0]:floors[places[destination]?.floor||0].name}</text></g></svg><div className="flyover-caption"><MapPin size={17}/><span>{lang==='hi'?'कैमरा प्रवेश से मंजिलों के बीच रास्ता दिखाता है':'The camera follows the route from the entrance to the destination'}</span></div></section>}
function directions(route,t,lang){if(!route.length)return[];return route.slice(1).map((p,i)=>lang==='hi'?`${p.floor!==route[i].floor?`लिफ्ट से ${['भूतल','पहली मंजिल','दूसरी मंजिल'][p.floor]} जाएँ। `:`${t.landmarks?.[p.id]||p.landmark} के पास पहुँचें। `}${placeName(p,t)}।`:`${p.floor!==route[i].floor?`Take the lift to the ${['ground','first','second'][p.floor]} floor. `:`Go ${p.landmark} to reach `}${p.name}.`)}
function Find(){const{t,lang,prefs,voiceLanguage}=useApp(),[lost,setLost]=useState(false),query=new URLSearchParams(location.search),initial=query.get('place')||'room3',dest=initial in places?initial:'room3',place=places[dest];return <><PageTitle title={t.find}/><PageBanner src="/images/hospital-corridor.jpg" alt="Hospital corridor for wayfinding" kicker={t.findWay} title={t.find}/><section className='navigation-game'><div className='navigation-game-head'><div><span className='eyebrow'>{t.navInteractive}</span><h2>{t.navHeroTitle}</h2><p>{t.navHeroBody}</p></div><span className='game-mode-pill'>{t.navHeroPill}</span></div><HospitalWayfinder translations={t} language={lang||'en'} voiceLanguage={voiceLanguage} accessibleByDefault={prefs.avoid} reducedMotionByDefault={Boolean(prefs.motion)} initialDestination={dest}/></section>{lost&&<section className="card notice"><h2>{t.closestHelp}</h2><FloorMap route={shortestPath(dest,'help')} destination="help"/><p>{t.showStaff}: <b>{t.destination} {place?placeName(place,t):''} / {place?placeName(place,t):''}</b></p><p>{t.directionsHint}</p></section>}<Btn onClick={()=>setLost(true)} icon={Accessibility}>{t.lost}</Btn><Urgent/></>}
function Settings(){const{t,lang,setLanguage,prefs,setPrefs,installPrompt,setInstallPrompt,background,setBackground,voiceLanguage}=useApp();const install=async()=>{if(!installPrompt)return;await installPrompt.prompt();await installPrompt.userChoice;setInstallPrompt(null)};return <div className="settings-page"><PageTitle title={t.settings}/><section className="card settings"><label>{t.language}<select value={lang||'en'} onChange={e=>setLanguage(e.target.value)}><option value="en">English</option><option value="hi">हिंदी</option><option value="ta">தமிழ்</option></select></label><label>Voice guide language<select aria-label="Voice guide language" value={voiceLanguage} onChange={e=>setPrefs(p=>({...p,voiceLanguage:e.target.value}))}><option value="en">English</option><option value="hi">हिंदी</option><option value="bn">বাংলা</option><option value="ta">தமிழ்</option></select><small>Used for spoken directions and read-aloud guidance.</small></label><label>{t.background||'Background video'}<select value={background} onChange={e=>{setBackground(e.target.value);localStorage.setItem('opd-background',e.target.value)}}><option value="current">{t.currentBackground||'Hospital film'}</option><option value="previous">{t.previousBackground||'Previous hospital film'}</option></select></label><label>{t.textSize}<input type="range" min="0" max="2" value={prefs.size} onChange={e=>setPrefs(p=>({...p,size:+e.target.value}))}/><span>{[t.smallType,t.mediumType,t.largeType][prefs.size]}</span></label>{[[t.contrast,'contrast'],[t.readAloud,'read'],[t.avoid,'avoid'],[lang==='hi'?'कम गति':'Reduce decorative motion','motion']].map(([name,k])=><label className="switch" key={k}><input type="checkbox" checked={Boolean(prefs[k])} onChange={e=>setPrefs(p=>({...p,[k]:e.target.checked}))}/>{name}</label>)}{installPrompt&&<button className="btn primary install-button" onClick={install}><Download/>{t.install}</button>}</section><Urgent/></div>}function StaffGate({children}){
  const{applyRemote,socket,t}=useApp();
  const[pin,setPin]=useState('');const[ready,setReady]=useState(false);const[error,setError]=useState('');
  useEffect(()=>{const token=localStorage.getItem('opd-staff-token');if(!token)return;fetch('/api/staff/state',{headers:{Authorization:`Bearer ${token}`}}).then(async r=>{if(!r.ok)throw Error('Staff PIN expired. Sign in again.');applyRemote(await r.json());setReady(true)}).catch(()=>{localStorage.removeItem('opd-staff-token');setReady(false)})},[]);
  const login=async(e)=>{e.preventDefault();setError('');try{const r=await fetch('/api/staff/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pin})});const result=await r.json();if(!r.ok)throw Error(result.error||'Unable to sign in.');localStorage.setItem('opd-staff-token',result.token);applyRemote(result.state);socket.current?.emit('staff:auth',result.token);setReady(true)}catch(err){setError(err.message)}};
  if(!ready)return <section className="staff-gate-layout"><div className="staff-gate-art"><img src="/images/care-team.jpg" alt="Hospital care team working together"/><div><span className="eyebrow">CITY DISTRICT HOSPITAL</span><h2>Care flows better together.</h2><p>Queue tools for a calmer, more coordinated front desk.</p></div></div><section className="card staff-pin-card"><span className="eyebrow">STAFF CONSOLE</span><h1>{t.staff}</h1><p>Enter the demo staff PIN to view and manage private queue details.</p><form onSubmit={login}><label>Staff PIN<input type="password" inputMode="numeric" value={pin} onChange={e=>setPin(e.target.value)} autoComplete="current-password" required/></label><button className="btn primary" type="submit">Sign in</button></form>{error&&<p role="alert" className="pin-error">{error}</p>}<small>Prototype PIN: 2468 · change it with the <code>STAFF_PIN</code> environment variable. Real hospitals need a proper staff login.</small></section></section>;
  return children;
}
