function Counter(){const{t,state,setState}=useApp(),[name,setName]=useState(''),[dep,setDep]=useState('medicine'),nav=useNavigate();const add=()=>{const d=departments.find(x=>x.id===dep),id=state.lastId+1,p={id,token:`${d.prefix}-${String(40+id).padStart(3,'0')}`,name:name||'Kamla',age:62,department:dep,status:'waiting',created:Date.now()};setState(s=>({...s,lastId:id,patients:[...s.patients,p]}));nav(`/slip/${id}`)};return <><PageTitle title={t.counter}/><PageBanner src="/images/registration-desk.jpg" alt="Hospital registration desk" kicker={t.counter} title={t.add}/><section className="card counter-card"><label>{t.name}<input value={name} onChange={e=>setName(e.target.value)}/></label><label>{t.doctor}<select value={dep} onChange={e=>setDep(e.target.value)}>{departments.map(d=><option key={d.id} value={d.id}>{deptName(d,t)}</option>)}</select></label><Btn onClick={add} className="primary" icon={Plus}>{t.add}</Btn></section><Urgent/></>}
function Board(){
  const{state,t,lang,setLang,connected,lastUpdated,voiceLanguage}=useApp();
  const [completed,setCompleted]=useState({});
  const [announcementNotice,setAnnouncementNotice]=useState('');
  const [autoAnnounce,setAutoAnnounce]=useState(()=>localStorage.getItem('opd-board-auto-announce')==='true');
  const activeCalls=departments.map(d=>({department:d,token:state.currentToken?.[d.id]||'—'})).filter(item=>item.token!=='—');
  const previousCalls=useRef(state.currentToken||{});
  const priorCurrent=useRef({});
  useEffect(()=>{
    const timers=[];
    for(const d of departments){
      const previous=priorCurrent.current[d.id];
      const current=state.currentToken?.[d.id]||'—';
      if(previous&&previous!=='—'&&previous!==current){
        setCompleted(value=>({...value,[d.id]:previous}));
        timers.push(setTimeout(()=>setCompleted(value=>{const next={...value};delete next[d.id];return next}),1400));
      }
      priorCurrent.current[d.id]=current;
    }
    return()=>timers.forEach(clearTimeout);
  },[state.currentToken]);
  const voiceAvailable=(code)=>speechSynthesis.getVoices().some(v=>v.lang.toLowerCase().startsWith(code));
  const announceCalls=(calls,code=voiceLanguage)=>{if(!calls.length)return false;const lines=calls.map(({department:d,token})=>{if(code==='hi')return `${t.token} ${token}, ${t.called} ${roomName(d,t,'hi')}`;if(code==='ta')return `${t.token} ${token}. ${t.deptNames?.[d.id]||d.name} பிரிவுக்குச் செல்லுங்கள்.`;if(code==='bn')return `টোকেন ${token}, অনুগ্রহ করে ${d.name} বিভাগে যান।`;return `Token ${token}. Please go to ${deptName(d,en)}, ${d.roomLabel}.`}).join('. ');const u=new SpeechSynthesisUtterance(lines);u.lang=code==='ta'?'ta-IN':code==='hi'?'hi-IN':code==='bn'?'bn-BD':'en-IN';const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith(code));if(code!=='en'&&!voice){setAnnouncementNotice(`${code==='hi'?'Hindi':code==='ta'?'Tamil':'Bengali'} speech voice is not installed in this browser.`);return false}if(voice)u.voice=voice;speechSynthesis.cancel();speechSynthesis.speak(u);setAnnouncementNotice(`Announcing ${calls.map(item=>item.token).join(', ')}`);return true};
  const announce=(code=voiceLanguage)=>{if(!activeCalls.length){setAnnouncementNotice('No tokens are being called right now. Call a patient from the staff dashboard first.');return}announceCalls(activeCalls,code)};
  useEffect(()=>{const latest=state.currentToken||{};const newlyCalled=departments.flatMap(department=>{const token=latest[department.id]||'—';return token!=='—'&&token!==previousCalls.current[department.id]?[{department,token}]:[]});previousCalls.current={...latest};if(autoAnnounce&&newlyCalled.length)announceCalls(newlyCalled,voiceLanguage)},[state.currentToken,autoAnnounce,voiceLanguage]);
  const tamilVoice=voiceAvailable('ta');
  const updatedTime=new Date(lastUpdated||Date.now()).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});
  return <div className="board board-live">
    <div className="board-hero"><div><span className="board-kicker">{t.boardLive||'LIVE QUEUE'}</span><h1>{t.hospital}</h1><p>{t.boardFlow||'Live patient flow'} <span>·</span> {t.boardWaitingNote||'Tokens move forward as care is completed.'}</p></div><div className={`board-live-pill ${connected?'is-live':'is-offline'}`}><i/><b>{connected?(t.boardLiveStatus||'LIVE'):(t.offline||'Offline')}</b><small>{t.boardUpdated||'Updated'} {updatedTime}</small></div></div>
    <div className="board-grid" aria-label={t.board||'Waiting-room board'}>{departments.map((d,index)=>{const queue=state.queues?.[d.id]||{},serving=state.currentToken?.[d.id]||'—',tokens=queue.nextTokens||[];const delay=state.statuses[d.id]?.state==='late'?state.statuses[d.id].delay:0;return <section className="board-department" key={d.id} style={{'--board-accent':d.color||['#248e82','#417bd2','#ce8b38','#8d68bd'][index%4]}}>
      <div className="board-dept-heading"><div><span className="board-room-label">{roomName(d,t,lang)}</span><h2>{deptName(d,t)}</h2></div><span className="board-dept-live"><i/>{t.boardLive||'LIVE'}</span></div>
      <div className="board-serving"><div><span className="board-label">{t.boardCallNow||t.serving}</span><small>{d.doctor}</small></div>{serving!=='—'?<strong className="board-serving-token" key={serving} aria-live="polite">{serving}</strong>:<span className="board-empty-serving">—</span>}</div>
      {completed[d.id]&&<div className="board-completed" key={completed[d.id]}><Check size={14}/><span>{completed[d.id]}</span><small>{t.boardCompleted||'completed'}</small></div>}
      <div className="board-queue-heading"><b>{t.boardNext||'Up next'}</b><span>{queue.waiting||0} {t.boardWaiting||'waiting'}</span></div>
      {tokens.length?<div className="board-people-line" aria-live="polite">{tokens.map((token,i)=><div className={`board-person-ticket ${i===0?'is-next':''}`} key={token}><span className="board-person-avatar" aria-hidden="true">🧍</span><b className="board-person-number">{lang==="hi"?`व्यक्ति ${i+1}`:lang==="ta"?`நபர் ${i+1}`:`Person ${i+1}`}</b><b>{token}</b><small>{i===0?(t.next||'Next'):t.waiting}</small></div>)}{queue.waiting>tokens.length&&<span className="board-more-tokens">+{queue.waiting-tokens.length}</span>}</div>:<div className="board-empty-queue"><span className="board-empty-dot"/><span>{t.boardQueueEmpty||'No one waiting right now'}</span></div>}
      <div className="board-queue-footer"><span><Clock size={14}/>{t.boardEstimate||'Estimated wait'}</span><b>{queue.waiting?`${queue.queueWaitMins??Math.ceil(queue.waiting*(queue.average||d.average)/5)*5} min`:'—'}</b>{delay>0&&<small>+{delay} min delay</small>}</div>
    </section>})}</div>
    <div className="board-actions"><div><p>{t.boardWaitingNote||'Waiting tokens move to Now serving when called and clear after care is complete.'}</p><small className="board-announce-status" role="status">{announcementNotice|| (activeCalls.length?`Ready to announce ${activeCalls.map(item=>item.token).join(', ')}`:'No active calls yet. Call a patient from the staff dashboard to enable announcements.')}</small></div><div className="board-announce-controls"><button className="board-announce" disabled={!activeCalls.length} onClick={()=>announce(voiceLanguage)}><Volume2/>{activeCalls.length?`${t.boardAnnouncement||'Announce called tokens'} · ${activeCalls.length}`:(t.boardAnnouncement||'Announce called tokens')}</button><label className="board-auto-announce"><input type="checkbox" checked={autoAnnounce} onChange={event=>{const enabled=event.target.checked;setAutoAnnounce(enabled);localStorage.setItem('opd-board-auto-announce',String(enabled));setAnnouncementNotice(enabled?'New calls will be announced automatically.':'Automatic announcements are off.')}}/>Auto-announce new calls</label>{lang==='ta'&&!tamilVoice&&<><button className="board-announce secondary" onClick={()=>announce('en')}>English</button><button className="board-announce secondary" onClick={()=>announce('hi')}>हिंदी</button></>}</div></div><Urgent/>
  </div>
}const rootKey='__opdSaathiRoot';const appRoot=window[rootKey]||(window[rootKey]=createRoot(document.getElementById('root')));appRoot.render(<App/>);
